select * from customer;

--1.what is the total revenue generated by male vs female customers?
select gender,sum(purchased_amount) as Total_revenue
from customer
group by gender;

--2.which customer used a discount but still spend more than the average purchased amount?

select customer_id,purchased_amount
from customer
where discount_applied='Yes' and purchased_amount >= (select Avg(purchased_amount)from customer);


--3.which are top five products with th ehighest avg review rating?

select item_purchased,round(avg(review_rating:: numeric),2) as "average_product_rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

--4.compare the avg purchased amounts between standard and express shipping?
select shipping_type,round(avg(purchased_amount),2)
 from customer
 where shipping_type in ('Standard','Express')
 group by shipping_type;


 --5.do subscribed customers spends more?compare avg spend and total revenue between subscribers 
 --and non subscribers.

 select subscription_status,
 count(customer_id) as total_customer,
 round(sum(purchased_amount),2) as total_revenue,
 round(avg(purchased_amount),2) as avg_spend
 from customer
 group by subscription_status
 order by total_revenue,avg_spend desc;

 --6.which five products have the highest % of purchases with discount applied?
 select item_purchased,
 round(100* sum(case when discount_applied='Yes' then 1 else 0 end)/Count(*),2) as discount_rate
 from customer
 group by item_purchased
 order by discount_rate
 desc limit 5;

 --7.segements customers into New,Returning and loyal based on their total_number of previous
 --purchases,and show the count of each segment.

With Customer_type as (
select customer_id,previous_purchases,
case when previous_purchases=1 then 'New'
     when previous_purchases between 2 and 10 then 'Returning'
     else 'Loyal' 
end as Customer_segment
from customer
)

select customer_segment,count(*) as "Number_of_customers"
from Customer_type
group by Customer_segment;

--8.what are the top 3 most purchased products within each category?

with item_counts as (
		select category,item_purchased,
		count(Customer_id) as total_orders,
        row_number()over (partition by category order by count(customer_id) desc)as item_rank
	    from customer
		group by category,item_purchased
	   )

	 select item_rank,category,item_purchased,total_orders
	 from item_counts
	 where item_rank<=3;

--9.Are customers who are repeated buyers(more than 5 previous purchases)also likely
--to subscribe?

select subscription_status,count(customer_id) as repeat_buyers
from customer
where previous_purchases>5 
group by subscription_status;


--10.what is the revenue contribution of each age group?


select age_group,sum(purchased_amount::numeric) as total_revenue
from customer
group by age_group
order by total_revenue desc






